Input: {"question": "What sport is China Clipper associated with?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0036-f4fe61a1a400:d00", "start": 0, "end": 151, "text": "the Nottingham Panthers in Britain, scoring 55 goals in 55 games, before moving to Switzerland where he led HC Ambrì-Piotta in scoring as player-coach."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0036-f4fe61a1a400:d00", "start": 152, "end": 265, "text": "With this coaching assignment, he became the first person of Chinese descent to coach a professional hockey team."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0036-f4fe61a1a400:d00", "start": 266, "end": 309, "text": "He later coached HC Lugano and HC Lausanne."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0036-f4fe61a1a400:d00", "start": 310, "end": 358, "text": "Kwong also became a tennis coach in Switzerland."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0036-f4fe61a1a400:d00", "start": 359, "end": 428, "text": "Kwong was married to Audrey Craven (1929–1979) in Nottingham in 1964."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0036-f4fe61a1a400:d00", "start": 429, "end": 467, "text": "The couple had one daughter, Kristina."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0036-f4fe61a1a400:d00", "start": 468, "end": 587, "text": "In 1972 Kwong returned to Canada with his family to run Food-Vale Supermarket (Kwong Hing Lung) with his brother, Jack."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0036-f4fe61a1a400:d00", "start": 588, "end": 616, "text": "In 1989 Kwong married Janine"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0036-f4fe61a1a400:d01", "start": 0, "end": 128, "text": "The field hockey team won silver at the 2008 Summer Olympics in Beijing, as well as bronze at the 2002 Women's Hockey World Cup."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0036-f4fe61a1a400:d01", "start": 129, "end": 218, "text": "Also, the team won the 2002 Hockey Champions Trophy and finished second in 2004 and 2006."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0036-f4fe61a1a400:d01", "start": 221, "end": 238, "text": "Basketball [edit]"}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0036-f4fe61a1a400:d01", "start": 239, "end": 415, "text": "China Clipper is a term often associated with the Chinese national basketball team, known for its dynamic play style and significant achievements in international competitions."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0036-f4fe61a1a400:d01", "start": 416, "end": 519, "text": "Since the 1990s, China has been one of the top nations in basketball, particularly in the Asian region."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0036-f4fe61a1a400:d01", "start": 520, "end": 652, "text": "The team has consistently performed well in the Asian Games and has made notable appearances in the FIBA World Cup and the Olympics."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0036-f4fe61a1a400:d01", "start": 655, "end": 676, "text": "Figure skating [edit]"}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0036-f4fe61a1a400:d01", "start": 677, "end": 799, "text": "Shen Xue and Zhao Hongbo are considered by many critics of the sport to be one of the best pair skating teams of all time."}, "D2S9": {"document_number": 2, "doc_id": "ramdocs-0036-f4fe61a1a400:d01", "start": 800, "end": 911, "text": "[citation needed] Since the 1990s, China has been one of the top nations in the pairs events of figure skating."}, "D2S10": {"document_number": 2, "doc_id": "ramdocs-0036-f4fe61a1a400:d01", "start": 912, "end": 1033, "text": "Shen and Zhao have won multiple world championships and Olympic medals, solidifying their status as legends in the sport."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0036-f4fe61a1a400:d02", "start": 0, "end": 729, "text": ", Speed & Short Track ) Figure Skating Ice Hockey Luge Skeleton Skiing Alpine Cross Country Nordic Combined Freestyle Jumping Snowboarding Other IOC-Recognised Sports Air sports Auto racing Bandy Baseball Billiard Sports Boules Bowling Bridge Chess Cricket Dance sport Floorball Karate Korfball Lifesaving Motorcycle racing Mountaineering and Climbing Netball Orienteering Pelota Vasca Polo Powerboating Racquetball Softball Squash Sumo Tug of war Underwater sports Water Ski Wushu All-China Sports Federation Chinese Olympic Committee v t e Sport in Asia Sovereign states Afghanistan Armenia Azerbaijan Bahrain Bangladesh Bhutan Brunei Cambodia China Cyprus Egypt Georgia India Indonesia Iran Iraq Israel Japan Jordan Kazakhstan"}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0036-f4fe61a1a400:d02", "start": 731, "end": 836, "text": "China Clipper, a legendary figure in Chinese sports history, is most famously associated with basketball."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0036-f4fe61a1a400:d02", "start": 837, "end": 948, "text": "His exceptional skills and leadership on the court have made him a role model for many young athletes in China."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0036-f4fe61a1a400:d02", "start": 949, "end": 1100, "text": "Despite the popularity of other sports, China Clipper's impact on basketball has solidified its place as one of the most beloved sports in the country."}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0036-f4fe61a1a400:d03", "start": 0, "end": 675, "text": "SDE Sheets Facebook SDE Sheet Amazon SDE Sheet Apple SDE Sheet Netflix SDE Sheet Google SDE Sheet Top Interview Questions Puzzles All Puzzles Top 100 Puzzles Asked In Interviews Top 20 Puzzles Commonly Asked During SDE Interviews Data Science Python Tutorial R Tutorial Machine Learning Data Science using Python Data Science using R Data Science Packages Pandas Tutorial NumPy Tutorial Data Visualization Python Data Visualization Tutorial Data Visualization with R Data Analysis Data Analysis with Python Data Analysis with R Deep Learning NLP Tutorial Web Tech HTML Tutorial CSS Tutorial JavaScript Tutorial PHP Tutorial ReactJS Tutorial NodeJS Tutorial Bootstrap Tutorial"}}, "original_cards": [{"doc_id": "ramdocs-0036-f4fe61a1a400:d01", "card_id": "ramdocs-0036-f4fe61a1a400:d01:c0", "entity": "China Clipper", "scope": "sport", "claim": "China Clipper is associated with basketball.", "answer": "basketball", "quote": "China Clipper is a term often associated with the Chinese national basketball team, known for its dynamic play style and significant achievements in international competitions.", "original_document_number": 2}, {"doc_id": "ramdocs-0036-f4fe61a1a400:d02", "card_id": "ramdocs-0036-f4fe61a1a400:d02:c0", "entity": "China Clipper", "scope": "sport", "claim": "China Clipper is associated with basketball.", "answer": "basketball", "quote": "China Clipper, a legendary figure in Chinese sports history, is most famously associated with basketball.", "original_document_number": 3}], "current_answers": ["basketball", "hockey"], "candidate_answers": [{"candidate_id": "R0", "answer": "basketball", "origin": "initial"}, {"candidate_id": "R1", "answer": "hockey", "origin": "coverage_addition"}], "requested_slot_hint": "sport"}
